class NomEscalaSueldoCargo extends BaseNomEscalaSueldoCargo {

    /**
     * Obtener un listado de los datos de las formas de pago.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de las formas de pago.
     */
    public static function obtenerListadoEscalaSueldoCargo($inicio = 0, $limite = 10) {

        //Devolviendo el listado de formas de pago en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomEscalaSueldoCargo')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray();
    }

    /**
     * Obtener la cantidad total de formas de pago.
     * 
     * @return int      Cantidad total de formas de pago.
     */
    public static function obtenerCantidadTotalEscalaSueldoCargo() {

        //Devolviendo la cantidad total de formas d epago.
        return Doctrine_Query::create()->select('COUNT(idescalasueldocargo) AS cantidad')
                        ->from('NomEscalaSueldoCargo')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener la forma de pago dado el identificador.
     * 
     * @param $idform        Identificador de la forma de pago.
     * @return NomFormaPago    Objeto forma de pago (clase del dominio).
     */
    public static function obtenerObjEscalaSueldoCargoDadoId($idescalasueldo) {
        return Doctrine::getTable('NomEscalaSueldoCargo')->find($idescalasueldo);
    }

}
